package com.northstar.crm.ui;import com.northstar.crm.domain.Notification;import com.northstar.crm.service.NotificationService;import com.vaadin.flow.component.UI;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.orderedlayout.VerticalLayout;import com.vaadin.flow.router.*;import jakarta.annotation.security.PermitAll;@Route(value="notifications",layout=MainLayout.class)@PageTitle("Notifications · Northstar")@PermitAll public class NotificationsView extends VerticalLayout {public NotificationsView(NotificationService service){var grid=new Grid<Notification>();grid.addColumn(Notification::getTitle).setHeader("Notification");grid.addColumn(Notification::getMessage).setHeader("Details").setFlexGrow(2);grid.addColumn(n->n.getCreatedAt().toString()).setHeader("Received");grid.addColumn(n->n.isReadFlag()?"Read":"New").setHeader("Status");grid.addComponentColumn(n->new Button("Open",e->{service.markRead(n.getId());UI.getCurrent().navigate(n.getTargetRoute());}));grid.setItems(service.mine());var panel=new VerticalLayout(grid);panel.addClassName("panel");add(UiKit.page("WORKFLOW SIGNALS","Notifications","Assignments, replies and renewal reminders for your account.",panel));setPadding(false);}}
